def money(x):return f'{x/10000:,.2f}'
def esc(x):return html.escape(str(x))
def table(headers,rows,cls=''):
 return '<div class="scroll"><table class="'+cls+'"><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def main():
 out=HERE/'report';out.mkdir(exist_ok=False)
 oldcurves=pd.read_csv(OLD/'analysis-v2/curves.csv');newcurves=pd.read_csv(HERE/'analysis-v2/curves.csv');paired=read(HERE/'comparison/paired-metrics.json');ann=read(HERE/'comparison/annual-winners-summary.json');orders=read(HERE/'audit/order-lifecycle.json')['rows'];winner=read(HERE/'comparison/winner-comparison.json');stocks=read(HERE/'analysis-v2/actual-stocks.json');sectors=read(HERE/'analysis-v2/actual-industries.json');stages=read(HERE/'analysis-v2/stages.json')
 colors={'T0':'#2764c7','T1':'#108877','S0':'#cf8745','S1':'#9b59b6'}
 fig,axs=plt.subplots(4,2,figsize=(15,15),sharex=True)
 for i,v in enumerate(colors):
  for df,label,ls,col in [(oldcurves,'旧版','--','#8792a5'),(newcurves,'修正后','-',colors[v])]:
   f=df.loc[df.account.eq(v+'_base')];dates=pd.to_datetime(f.date)
   axs[i,0].plot(dates,f.nav/1e4,label=label,ls=ls,color=col,lw=1.25);axs[i,1].plot(dates,f.drawdown*100,label=label,ls=ls,color=col,lw=1)
  axs[i,0].set_title(v+' 净资产（万元，对数轴）',fontproperties=FONT);axs[i,0].set_yscale('log');axs[i,1].set_title(v+' 日收盘回撤（%）',fontproperties=FONT)
  for ax in axs[i]:ax.grid(alpha=.2);ax.legend(prop=FONT)
 fig.tight_layout();fig.savefig(out/'curves.png',dpi=130);plt.close(fig)
 rows=[]
 for x in paired:
  if not x['account'].endswith('_base'):continue
  a,b=x['old'],x['new'];rows.append([esc(x['account'].split('_')[0]),pct(a['net_return']),'<b>'+pct(b['net_return'])+'</b>',pct(a['max_drawdown']),'<b>'+pct(b['max_drawdown'])+'</b>',money(b['final_nav']),pct(b['win_rate']),str(b['unique_stocks']),pct(b['mean_exposure'])])
 base=table(['策略','旧收益','新收益','旧最大回撤','新最大回撤','新期末万元','新已结清胜率','新买入股票数','新平均股票仓位'],rows)
 stresses=table(['账户','旧收益','新收益','旧回撤','新回撤','收益变化pp','回撤变化pp'],[[esc(x['account']),pct(x['old']['net_return']),pct(x['new']['net_return']),pct(x['old']['max_drawdown']),pct(x['new']['max_drawdown']),f'{x["return_change_pp"]:+.2f}',f'{x["drawdown_change_pp"]:+.2f}'] for x in paired])
 stagehtml=table(['账户','阶段','新收益','新回撤','平均仓位'],[[esc(x['account']),esc(x['period']),pct(x['net_return']),pct(x['max_drawdown']),pct(x['mean_exposure'])] for x in stages if x['account'].endswith('_base')])
 lifecycle=table(['策略','新订单数','到期取消','其中部分成交取消','取消后再获资金次数','短历史实际买单','短历史股票数','买单最长等待'],[[esc(x['account']),x['reservations'],x['daily_expirations'],x['partial_balance_expirations'],x['reaccepted_after_expiry'],x['short_history_filled_orders'],x['short_history_unique_stocks'],'1市场日'] for x in orders if x['account'].endswith('_base')])
 annual=table(['策略','固定年度大赢家窗口','旧参与过','新参与过','新增参与','失去参与','旧平均持有覆盖','新平均持有覆盖','新平均账户权重'],[[esc(x['account']),240,x['old_participated'],x['new_participated'],x['newly_participated'],x['lost_participation'],pct(x['old_mean_coverage']),pct(x['new_mean_coverage']),pct(x['new_mean_weight'])] for x in ann])
 missed=table(['策略','未参与主因','窗口数'],[[esc(x['account']),esc(REASON.get(k,k)),v] for x in ann for k,v in sorted(x['new_missed_reasons'].items(),key=lambda kv:-kv[1])])
 basew=[x for x in winner if x['account'].endswith('_base') and x['window_type']=='annual' and x['current_cap_disposition']=='selected'];keytop=sorted({(x['symbol'],x['year'],x['price_return']) for x in basew},key=lambda x:-x[2])[:16];topkeys={(x[0],x[1]) for x in keytop}
 wt=table(['账户','股票 / 年份','诊断涨幅','旧→新参与','新主因','新首次持有','新持有日覆盖','新平均仓位','新窗口贡献万元'],[[esc(x['account']),esc(f'{x["name"]} {x["symbol"]} / {x["year"]}'),pct(x['price_return']),('是' if x['old_participated'] else '否')+'→'+('是' if x['new_participated'] else '否'),esc(REASON.get(x['new_reason'],x['new_reason'])),esc(x['new_first'] or '—'),pct(x['new_coverage']),pct(x['new_weight']),money(x['new_contribution'])] for x in sorted(basew,key=lambda x:(-x['price_return'],x['account'])) if (x['symbol'],x['year']) in topkeys], 'filtered')
 actual=''
 for v in colors:
  aid=v+'_base';ss=sorted([x for x in stocks if x['account']==aid],key=lambda x:-x['net_contribution']);gg=sorted([x for x in sectors if x['account']==aid],key=lambda x:-x['net_contribution'])
  actual+='<article data-account="'+aid+'"><h3>'+v+' 实际买入</h3>'+table(['行业','净贡献万元','累计买入万元','股票数','股票'],[[esc(x['industry']),money(x['net_contribution']),money(x['buy_gross']),x['unique_stocks'],esc(x['stocks'])] for x in gg])+ '<details><summary>全部实际买入股票（按贡献排序，含亏损）</summary>'+table(['股票','行业','净贡献万元','累计买入万元','实际周期','首次买入'],[[esc(x['name']+' '+x['symbol']),esc(x['industry']),money(x['net_contribution']),money(x['buy_gross']),x['campaigns'],esc(x['first_buy'][:10])] for x in ss])+'</details></article>'
 hist=[x for x in read(HERE/'diagnosis/history-attribution.json') if x['version']=='new' and x['account'].endswith('_base')]
